async function previewHtml(){const selected=productList().filter(p=>builder.products[p.id]?.selected),parts=[];for(const p of selected){const row=builder.products[p.id]||{};parts.push(await labelHtml(p,row,{preview:true}))}return parts.join('')||'<div class="pl-preview-empty">Выберите товар для предпросмотра.</div>'}
const nextFrame=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
