function collectRowsFromUi(){document.querySelectorAll('[data-label-product-row]').forEach(el=>{const id=el.dataset.labelProductRow,row=builder.products[id]||{};el.querySelectorAll('[data-pl-field]').forEach(input=>{const key=input.dataset.plField;row[key]=input.type==='checkbox'?input.checked:input.type==='number'?Math.max(1,Number(input.value||1)):input.value});builder.products[id]=row});saveBuilder()}
